SELECT empresa.nome, empresa.capital, situacao_cadastral.descricao FROM empresa JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo WHERE situacao_cadastral.descricao = 'ATIVA' ORDER BY empresa.capital DESC LIMIT 5	cnpjPT
SELECT natureza_juridica.descricao, SUM(empresa.capital) FROM empresa JOIN natureza_juridica ON empresa.codigo_natureza_juridica = natureza_juridica.codigo JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo WHERE situacao_cadastral.descricao = 'ATIVA' GROUP BY natureza_juridica.descricao ORDER BY SUM(empresa.capital) DESC LIMIT 5	cnpjPT
SELECT natureza_juridica.descricao, COUNT(estabelecimento.cnpj_basico) FROM estabelecimento JOIN empresa ON estabelecimento.cnpj_basico = empresa.cnpj_basico JOIN natureza_juridica ON empresa.codigo_natureza_juridica = natureza_juridica.codigo JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo WHERE situacao_cadastral.descricao = 'ATIVA' GROUP BY natureza_juridica.descricao ORDER BY COUNT(estabelecimento.cnpj_basico) DESC	cnpjPT
SELECT empresa.nome, natureza_juridica.descricao FROM empresa JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN natureza_juridica ON empresa.codigo_natureza_juridica = natureza_juridica.codigo JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo WHERE empresa.capital > 5000000 AND estabelecimento.estado = 'SP' AND situacao_cadastral.descricao = 'ATIVA'	cnpjPT
SELECT cnae.nome, AVG(empresa.capital) FROM empresa JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN cnae ON estabelecimento.codigo_cnae_principal = cnae.codigo WHERE estabelecimento.data_inicio_atividade > '20151231' AND estabelecimento.cnpj_basico IN (SELECT DISTINCT socio.cnpj_basico FROM socio JOIN qualificacao ON socio.codigo_qualificacao_socio = qualificacao.codigo WHERE qualificacao.descricao = 'Administrador') GROUP BY cnae.nome HAVING COUNT(DISTINCT empresa.cnpj_basico) > 3 ORDER BY AVG(empresa.capital) DESC	cnpjPT
SELECT cidade.nome, COUNT(estabelecimento.cnpj_basico) FROM estabelecimento JOIN cidade ON estabelecimento.codigo_cidade = cidade.codigo WHERE estabelecimento.data_inicio_atividade >= '20210101' GROUP BY cidade.nome ORDER BY COUNT(estabelecimento.cnpj_basico) DESC LIMIT 5	cnpjPT
SELECT empresa.nome, cnae.nome, motivo_situacao_cadastral.descricao FROM empresa JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN cnae ON estabelecimento.codigo_cnae_principal = cnae.codigo JOIN motivo_situacao_cadastral ON estabelecimento.codigo_motivo_situacao_cadastral = motivo_situacao_cadastral.codigo WHERE estabelecimento.estado = 'SP'	cnpjPT
SELECT cnae.nome, COUNT(estabelecimento.cnpj_basico) FROM estabelecimento JOIN cnae ON estabelecimento.codigo_cnae_principal = cnae.codigo GROUP BY cnae.nome ORDER BY COUNT(estabelecimento.cnpj_basico) DESC LIMIT 5	cnpjPT
SELECT qualificacao.descricao, COUNT(socio.cnpj_basico), AVG(empresa.capital) FROM socio JOIN empresa ON socio.cnpj_basico = empresa.cnpj_basico JOIN qualificacao ON socio.codigo_qualificacao_socio = qualificacao.codigo GROUP BY qualificacao.descricao HAVING COUNT(socio.cnpj_basico) >= 10 ORDER BY COUNT(socio.cnpj_basico) DESC	cnpjPT
SELECT natureza_juridica.descricao, COUNT(*) FROM empresa JOIN natureza_juridica ON empresa.codigo_natureza_juridica = natureza_juridica.codigo JOIN porte_empresa ON empresa.codigo_porte_empresa = porte_empresa.codigo WHERE porte_empresa.descricao = 'DEMAIS' GROUP BY natureza_juridica.descricao ORDER BY COUNT(*) DESC LIMIT 5	cnpjPT
