SELECT empresa.nome, cnae.nome FROM empresa JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN tributacao ON empresa.cnpj_basico = tributacao.cnpj_basico JOIN cnae ON estabelecimento.codigo_cnae_principal = cnae.codigo WHERE tributacao.opcao_pelo_simples_nacional = 'S' AND estabelecimento.data_inicio_atividade > '20151231'	cnpjPT
SELECT estabelecimento.estado, COUNT(*) FROM estabelecimento JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo WHERE situacao_cadastral.descricao = 'ATIVA' GROUP BY estabelecimento.estado ORDER BY COUNT(*) DESC LIMIT 5	cnpjPT
