SELECT qualificacao.descricao, COUNT(socio.cnpj_basico) FROM socio JOIN qualificacao ON socio.codigo_qualificacao_socio = qualificacao.codigo GROUP BY qualificacao.descricao ORDER BY COUNT(socio.cnpj_basico) DESC LIMIT 5	cnpjPT
SELECT natureza_juridica.descricao, COUNT(empresa.cnpj_basico) FROM empresa JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN natureza_juridica ON empresa.codigo_natureza_juridica = natureza_juridica.codigo JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo WHERE situacao_cadastral.descricao = 'ATIVA' GROUP BY natureza_juridica.descricao ORDER BY COUNT(empresa.cnpj_basico) DESC	cnpjPT
SELECT empresa.nome, COUNT(socio.cpf_ou_cnpj) FROM empresa JOIN porte_empresa ON empresa.codigo_porte_empresa = porte_empresa.codigo JOIN socio ON empresa.cnpj_basico = socio.cnpj_basico WHERE porte_empresa.descricao = 'MICRO EMPRESA' GROUP BY empresa.nome ORDER BY COUNT(socio.cpf_ou_cnpj) DESC	cnpjPT
SELECT porte_empresa.descricao, COUNT(estabelecimento.cnpj_basico) FROM estabelecimento JOIN empresa ON estabelecimento.cnpj_basico = empresa.cnpj_basico JOIN porte_empresa ON empresa.codigo_porte_empresa = porte_empresa.codigo JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo WHERE situacao_cadastral.descricao = 'ATIVA' GROUP BY porte_empresa.descricao ORDER BY COUNT(estabelecimento.cnpj_basico) DESC	cnpjPT
SELECT cnae.nome, COUNT(empresa.cnpj_basico), AVG(empresa.capital) FROM empresa JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN cnae ON estabelecimento.codigo_cnae_principal = cnae.codigo WHERE empresa.cnpj_basico IN (SELECT DISTINCT socio.cnpj_basico FROM socio JOIN qualificacao ON socio.codigo_qualificacao_socio = qualificacao.codigo JOIN estabelecimento ON socio.cnpj_basico = estabelecimento.cnpj_basico JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo JOIN tributacao ON socio.cnpj_basico = tributacao.cnpj_basico WHERE qualificacao.descricao = 'Sócio-Administrador' AND situacao_cadastral.descricao = 'ATIVA' AND tributacao.opcao_pelo_simples_nacional = 'S') GROUP BY cnae.nome HAVING COUNT(empresa.cnpj_basico) > 5 ORDER BY COUNT(empresa.cnpj_basico) DESC	cnpjPT
SELECT porte_empresa.descricao, COUNT(socio.cnpj_basico) FROM socio JOIN empresa ON socio.cnpj_basico = empresa.cnpj_basico JOIN porte_empresa ON empresa.codigo_porte_empresa = porte_empresa.codigo GROUP BY porte_empresa.descricao ORDER BY COUNT(socio.cnpj_basico) DESC	cnpjPT
SELECT cidade.nome, COUNT(*) FROM empresa JOIN porte_empresa ON empresa.codigo_porte_empresa = porte_empresa.codigo JOIN estabelecimento ON empresa.cnpj_basico = estabelecimento.cnpj_basico JOIN cidade ON estabelecimento.codigo_cidade = cidade.codigo WHERE porte_empresa.descricao = 'DEMAIS' GROUP BY cidade.nome ORDER BY COUNT(*) DESC LIMIT 5	cnpjPT
SELECT cidade.nome, COUNT(estabelecimento.cnpj_basico) FROM estabelecimento JOIN cidade ON estabelecimento.codigo_cidade = cidade.codigo GROUP BY cidade.nome ORDER BY COUNT(estabelecimento.cnpj_basico) DESC LIMIT 5	cnpjPT
SELECT cnae.nome, COUNT(DISTINCT estabelecimento.cnpj_basico), SUM(empresa.capital), COUNT(DISTINCT socio.cpf_ou_cnpj) FROM estabelecimento JOIN situacao_cadastral ON estabelecimento.codigo_situacao_cadastral = situacao_cadastral.codigo JOIN socio ON estabelecimento.cnpj_basico = socio.cnpj_basico JOIN pais ON socio.codigo_pais = pais.codigo JOIN cnae ON estabelecimento.codigo_cnae_principal = cnae.codigo JOIN empresa ON estabelecimento.cnpj_basico = empresa.cnpj_basico WHERE situacao_cadastral.descricao = 'ATIVA' AND pais.nome != 'BRASIL' GROUP BY cnae.nome ORDER BY COUNT(DISTINCT estabelecimento.cnpj_basico) DESC LIMIT 3	cnpjPT
SELECT cnae.nome, COUNT(estabelecimento.cnpj_basico) FROM estabelecimento JOIN cidade ON estabelecimento.codigo_cidade = cidade.codigo JOIN cnae ON estabelecimento.codigo_cnae_principal = cnae.codigo WHERE cidade.nome = 'CURITIBA' GROUP BY cnae.nome ORDER BY COUNT(estabelecimento.cnpj_basico) DESC LIMIT 3	cnpjPT
